import 'dart:convert';import 'package:dio/dio.dart';import 'package:flutter/material.dart';import '../../../core/network/api_endpoints.dart';import '../../../core/network/dio_client.dart';import '../../../shared/widgets/app_card.dart';
class AndroidRuntimePage extends StatefulWidget{const AndroidRuntimePage({super.key});@override State<AndroidRuntimePage>createState()=>_S();}class _S extends State<AndroidRuntimePage>{Map<String,dynamic>? data;List<String>logs=[];bool busy=false;@override void initState(){super.initState();load();}Future<void>load()async{final r=await DioClient.instance.dio.get(ApiEndpoints.androidRuntimeStatus);if(mounted)setState(()=>data=Map<String,dynamic>.from(r.data as Map));}Future<void>install(String name)async{setState((){busy=true;logs=[];});try{final r=await DioClient.instance.dio.post<ResponseBody>(ApiEndpoints.androidRuntimeInstall,data:{'name':name},options:Options(responseType:ResponseType.stream));await for(final bytes in r.data!.stream){final text=utf8.decode(bytes);for(final line in text.split('\n')){if(line.startsWith('data: '))setState(()=>logs.add(line.substring(6).replaceAll(r'\n','\n')));}}}finally{if(mounted){setState(()=>busy=false);await load();}}}Future<void>uninstall(String n)async{await DioClient.instance.dio.post(ApiEndpoints.androidRuntimeUninstall,data:{'name':n});await load();}@override Widget build(BuildContext c){final supported=data?['supported']==true;final rs=data?['runtimes'] is List?data!['runtimes']as List:[];return Scaffold(backgroundColor:Colors.transparent,appBar:AppBar(title:const Text('Android 运行时')),body:data==null?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(20),children:[if(!supported)const AppCard(child:Text('当前面板不支持 Android/Magisk 运行时管理')),for(final x in rs.whereType<Map>())AppCard(margin:const EdgeInsets.only(bottom:8),child:ListTile(title:Text(x['name'].toString()),subtitle:Text('${x['version']??'未安装'}\n${x['path']??''}'),trailing:Wrap(children:[IconButton(onPressed:busy?null:()=>install(x['name'].toString()),icon:const Icon(Icons.download)),IconButton(onPressed:x['installed']==true?()=>uninstall(x['name'].toString()):null,icon:const Icon(Icons.delete_outline))]))),if(logs.isNotEmpty)AppCard(child:SelectableText(logs.join('\n'),style:const TextStyle(fontFamily:'monospace')))]));}}
